<?php $title='Banner';require '_head.php';$msg='';
try{
if(isset($_GET['delete'])){$pdo->prepare('DELETE FROM banners WHERE id=?')->execute([(int)$_GET['delete']]);header('Location: banners.php');exit;}
if($_SERVER['REQUEST_METHOD']==='POST'){$image=upload_image($_FILES['image']??null,'banners');$pdo->prepare('INSERT INTO banners(eyebrow,title,subtitle,image,button_text,button_url,sort_order,active) VALUES(?,?,?,?,?,?,0,1)')->execute([$_POST['eyebrow'],$_POST['title'],$_POST['subtitle'],$image,$_POST['button_text'],$_POST['button_url']]);header('Location: banners.php?saved=1');exit;}
}catch(Throwable $e){$msg=$e->getMessage();}
$rows=$pdo->query('SELECT * FROM banners ORDER BY id DESC')->fetchAll();?><h1>Banner</h1><?php if($msg):?><div class="alert"><?=e($msg)?></div><?php endif;?><div class="panel"><form method="post" enctype="multipart/form-data"><input name="eyebrow" placeholder="Eyebrow"><input name="title" placeholder="Judul" required><textarea name="subtitle" placeholder="Subjudul"></textarea><label class="upload-label">Foto banner<input type="file" name="image" accept="image/jpeg,image/png,image/webp" required><small>JPG, PNG, WebP • maksimal 5 MB</small></label><input name="button_text" placeholder="Teks tombol"><input name="button_url" placeholder="/produk.php"><button>Simpan Banner</button></form></div><div class="panel"><?php foreach($rows as $r):?><p><?php if($r['image']):?><img class="thumb" src="<?=e($r['image'])?>" alt=""><?php endif;?> <?=e($r['title'])?> — <a href="?delete=<?=$r['id']?>" onclick="return confirm('Hapus?')">Hapus</a></p><?php endforeach;?></div><?php require '_foot.php';?>